package main
import("net/http/httptest";"testing";"strings")
func TestGitHubCORSStillRequiresToken(t *testing.T){b:=&bridge{host:"127.0.0.1:19091",token:"test-token"};for _,key:=range []string{"", "wrong", "test-token"}{r:=httptest.NewRequest("GET","http://"+b.host+"/api/status",nil);r.Header.Set("Origin","https://anshaer.github.io");r.Header.Set("X-Bridge-Key",key);w:=httptest.NewRecorder();b.handler().ServeHTTP(w,r);if w.Header().Get("Access-Control-Allow-Origin")!="https://anshaer.github.io"{t.Fatal("GitHub CORS missing")};if key==b.token {if w.Code!=200 {t.Fatal(w.Code)}} else if w.Code!=403 {t.Fatal("unauthorized accepted")}}}
func TestPreflightAndLauncher(t *testing.T){b:=&bridge{host:"127.0.0.1:19091",token:"test-token"};for _,origin:=range []string{"https://anshaer.github.io","https://evil.example","null"}{r:=httptest.NewRequest("OPTIONS","http://"+b.host+"/api/frame",nil);r.Header.Set("Origin",origin);w:=httptest.NewRecorder();b.handler().ServeHTTP(w,r);if origin=="https://anshaer.github.io" {if w.Code!=204 {t.Fatal(w.Code)}} else if w.Code!=403 || w.Header().Get("Access-Control-Allow-Origin")!="" {t.Fatal("unknown origin accepted")}};r:=httptest.NewRequest("GET","http://"+b.host+"/",nil);w:=httptest.NewRecorder();b.handler().ServeHTTP(w,r);if w.Code!=200||!strings.Contains(w.Body.String(),"test-token")||strings.Contains(w.Body.String(),"__BRIDGE_KEY__"){t.Fatal("launcher token not replaced")}}
